def attente_moyenne(clients):
    if not clients:
        return 0
    fin = 0
    total = 0
    for arrivee, duree in clients:
        debut = max(arrivee, fin)
        total += debut - arrivee
        fin = debut + duree
    return round(total / len(clients), 1)

