from collections import deque

def tourniquet(taches, tranche):
    file = deque((nom, temps) for nom, temps in taches)
    fini = []
    while file:
        nom, temps = file.popleft()
        temps -= tranche
        if temps <= 0:
            fini.append(nom)
        else:
            file.append((nom, temps))
    return fini
